G_LS_LABEL = {'ensemble_awareness': 'Ensemble Awareness', 'musical_ear': 'Musical Ear', 'rehearsal_focus': 'Rehearsal Focus',
              'creative_risk': 'Creative Risk-Taking', 'care_of_instruments': 'Care of Instruments', 'engagement': 'Engagement'}

bank = json.load(open(SRC, encoding='utf-8'))
meta = bank['metadata']
s5 = [s for s in bank['statements'] if s['stage'] == 'Stage 5']
byid = {s['id']: s for s in s5}
assert set(R) <= set(byid), set(R) - set(byid)

added = []
for sub, five in G_LS.items():
    assert len(five) == 5, sub
    for i, text in enumerate(five):
        added.append({'id': f'S5_LS_G_{TC[i]}_{sub.upper()}', 'stage': 'Stage 5', 'commentType': 'learning_strength',
                      'category': 'G', 'categoryLabel': 'General', 'subcategory': sub, 'subcategoryLabel': G_LS_LABEL[sub],
                      'tier': TIERS[i], 'tierCode': TC[i], 'instrument': None, 'unit': None, 'specificity': None,
                      'course': None, 'stageCourse': None, 'courseProfile': None, 'topic': None, 'voiceTag': None,
                      'statementLength': None, 'text': text,
                      'tags': ['learning_strength', 'stage5', 'year9', 'year10', 'G', 'general', TIERS[i].lower(), sub]})
assert not ({r['id'] for r in added} & {s['id'] for s in bank['statements']})

final = {s['id']: R.get(s['id'], s['text']) for s in s5}
final.update({r['id']: r['text'] for r in added})
ctype = {**{s['id']: s['commentType'] for s in s5}, **{r['id']: r['commentType'] for r in added}}
PRON = re.compile(r'\b(he|she|they|his|her|their|him|them|hers|theirs|himself|herself|themselves|I|me|my|we|our|you|your)\b', re.I)
problems, cnt = [], C.Counter(final.values())
for id_, t in final.items():
    if not LO <= len(t) <= HI: problems.append((id_, len(t), t))
    if PRON.search(t): problems.append((id_, 'pronoun ' + PRON.search(t).group()))
    if not t.endswith('.') or re.search(r'[.!?]\s+[A-Z]', t): problems.append((id_, 'not one sentence'))
    if re.search(r'\b(limited|poor|weak|fail|lazy|careless)\b', t, re.I): problems.append((id_, 'deficit'))
    if re.search(r'ize\b|izing|color|center\b', t): problems.append((id_, 'US spelling'))
    if cnt[t] > 1: problems.append((id_, 'duplicate', t))
    w = t.split()[0]
    if id_ in R or id_.startswith('S5_LS_G'):
        if ctype[id_] == 'learning_strength' and not w.endswith('s'): problems.append((id_, 'strength not 3rd person'))
        if ctype[id_] == 'strategy_to_improve' and w.endswith('s') and w not in ('Focus', 'Consolidate'.rstrip('s')): problems.append((id_, 'strategy not imperative'))
if problems:
    for p in problems: print('PROBLEM', p)
    sys.exit(1)

changes = [{'id': i, 'old': byid[i]['text'], 'new': t} for i, t in R.items() if byid[i]['text'] != t]
for i, t in R.items(): byid[i]['text'] = t
bank['statements'].extend(added)
json.dump({'changed': changes, 'added': [{'id': r['id'], 'text': r['text']} for r in added]},
          open('data/diffs/v5.7_to_v5.9_stage5.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
for sub in G_LS_LABEL:
    if sub not in meta['generalSubcategories']: meta['generalSubcategories'].append(sub)
meta['sentralCharLimits']['Stage 5']['targetRange'] = [250, 300]
json.dump(bank, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
L = [len(t) for t in final.values()]
print(f'Stage 5: changed {len(changes)}, added {len(added)}; sentence lengths {min(L)}-{max(L)}; comments {3*min(L)+2}-{3*max(L)+2}')
